//! Checks the downside measures against independent implementations: the conditional drawdown
//! at risk against the linear programme of Chekhlov, Uryasev and Zabarankin (SciPy), the Ulcer
//! index against pandas, the downside and upside betas against least squares and the capture
//! ratios against empyrical's definition, and each asset's contribution to expected shortfall
//! against the derivative of the portfolio's expected shortfall (the Euler property). The fixture
//! is generated by `scripts/reference/downside.py`.

#![allow(clippy::unwrap_used)]

use finalytics_risk::*;
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let text = match name {
        "downside" => include_str!("fixtures/downside.json"),
        _ => include_str!("fixtures/statistics.json"),
    };
    serde_json::from_str(text).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[track_caller]
fn close(actual: f64, expected: &Value, tolerance: f64, what: &str) {
    let expected = expected.as_f64().unwrap();
    let scale = expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tolerance * scale,
        "{what}: {actual} against the reference {expected}"
    );
}

#[test]
fn drawdown_measures_and_conditional_betas_match_the_reference() {
    let returns = fixture("statistics");
    let expected = fixture("downside");
    for (case, reference) in returns["cases"]
        .as_array()
        .unwrap()
        .iter()
        .zip(expected["cases"].as_array().unwrap())
    {
        let name = case["name"].as_str().unwrap();
        let options: StatisticsOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let r = floats(&case["returns"]);
        let b = floats(&case["benchmark"]);
        let stats = statistics(&r, &options).unwrap();
        close(
            stats.conditional_drawdown_at_risk,
            &reference["conditional_drawdown_at_risk"],
            1e-10,
            &format!("{name}: CDaR"),
        );
        close(
            stats.ulcer_index,
            &reference["ulcer_index"],
            1e-12,
            &format!("{name}: Ulcer index"),
        );
        assert!(stats.conditional_drawdown_at_risk >= stats.max_drawdown);
        let relative = relative_statistics(&r, &b, &options).unwrap();
        let rel = &reference["relative"];
        for (field, value) in [
            ("downside_beta", relative.downside_beta),
            ("upside_beta", relative.upside_beta),
            ("downside_capture", relative.downside_capture),
            ("upside_capture", relative.upside_capture),
        ] {
            close(
                value.unwrap(),
                &rel[field],
                1e-10,
                &format!("{name}: {field}"),
            );
        }
    }
}

#[test]
fn shortfall_contributions_are_its_derivatives() {
    let fixture = fixture("downside");
    let case = &fixture["shortfall"];
    let labels: Vec<String> = case["labels"]
        .as_array()
        .unwrap()
        .iter()
        .map(|l| l.as_str().unwrap().to_owned())
        .collect();
    let columns = case["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect();
    let scenarios = ReturnsTable::new(labels, columns).unwrap();
    let weights = floats(&case["weights"]);
    let found = shortfall_decomposition(&weights, &scenarios, 0.95).unwrap();
    close(
        found.expected_shortfall,
        &case["expected_shortfall"],
        1e-12,
        "expected shortfall",
    );
    for (c, expected) in found
        .contributions
        .iter()
        .zip(case["contributions"].as_array().unwrap())
    {
        // Central differences of a piecewise-linear function, to about 1e-9.
        close(c.component, expected, 1e-8, &c.label);
    }
    let total: f64 = found.contributions.iter().map(|c| c.component).sum();
    assert!((total - found.expected_shortfall).abs() < 1e-15);
    let groups = group_contributions(&found.contributions, |k, _| {
        if k < 2 { "first" } else { "second" }.to_owned()
    });
    let shares: f64 = groups.iter().map(|g| g.share.unwrap()).sum();
    assert!((shares - 1.0).abs() < 1e-12);
}
